makeImmutable() {
  if (this.mImmutable) {
    return;
  }

  for (const ritem of this.mRecurrenceItems) {
    if (ritem.isMutable) {
      ritem.makeImmutable();
    }
  }

  for (const ex in this.mExceptionMap) {
    const item = this.mExceptionMap[ex];
    if (item.isMutable) {
      item.makeImmutable();
    }
  }

  this.mImmutable = true;
